head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[tabControl > P > useConfirmMessage]<br/>addTab() 메소드로 Tab 페이지를 추가할때 동일 ID 의 Tab 페이지가 있는 경우 처리 방법을 설정합니다.",
    "validation" : [
        "addTab() 메소드의 tabOptions.openAction 파라미터를 설정하지 않고 실행한 경우 동작합니다.",
        "미설정 또는 false 설정 시 addTab() 메소드의 실행이 취소되고 Tab 페이지가 추가되지 않습니다.",
        "true 설정 시 Confirm 팝업창이 표시되며 사용자의 선택에 따라 처리합니다.",
        "true 설정 시 Confirm 팝업창엔 cofirmMessage 속성값이 출력되며, 기본값은 '[{tabOptions.label 파라미터값}]탭이 존재합니다. 기존의 탭을 사용하시려면 '확인'을 새로운 탭을 생성하시려면 '취소'를 선택하세요.' 입니다.",
        "'확인' 선택 시 confirmTrueAction 속성값에 따라 처리합니다.",
        "'취소' 선택 시 confirmFalseAction 속성값에 따라 처리합니다.",
        "Tabs 의 ID 를 기준으로 Tab 페이지의 중복 여부를 판단합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 조건 설정   
    let properties = {        
        useConfirmMessage : con_useConfirmMessage.getText(),   
        confirmTrueAction : "new",
        confirmFalseAction : "select",
    };

    let cList = $c.gcm.createCList(properties);   
    let eList = '';

    let grp_comp = $c.gcm.getTestGroup();    
    let strTarget = '';
    let strNameSpace = $c.gcm.getNameSpace();

    $c.gcm.createLabel('label="confirmTrueAction=new, confirmFalseAction=select 설정된 상태임"', '', 'label1');

    strTarget += '<w2:tabControl ' + strNameSpace + ' ' + cList + ' ' + eList + ' id="" style="width:500px;height:200px;">';
    strTarget += '<w2:tabs disabled="false" style="height:40px;" id="tabs1" label="Tabs1"></w2:tabs>';
    strTarget += '<w2:tabs disabled="false" style="height:40px;" id="tabs2" label="Tabs2"></w2:tabs>';
    strTarget += '<w2:content src="/sample/common_link/tabControl_link_1.xml" style="height:160px;" id="content1">';
    strTarget += '<w2:button style="width:80px; width:130px; height:50px;" id="content1_child" label="content1_child"></w2:button>';
    strTarget += '</w2:content>';
    strTarget += '<w2:content style="height:160px" id="content2">';
    strTarget += '<xf:input id="content2_child" style="width:144px; height:21px; " initValue="content2_child"></xf:input>';
    strTarget += '</w2:content>';
    strTarget += '</w2:tabControl>';

    // target 생성
    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "tabControl",
        strTarget,
        grp_comp
    );
}



scwin.getAfterAction = function () {    
    target1.setSelectedTabIndex(2);    

    let selectedIndex = target1.getSelectedTabIndex();  
    let text = target1.render.textContent;

    wf_body_bottom.getObj("scwin").setReturnValue("getSelectedTabIndex : " + selectedIndex);          
    wf_body_bottom.getObj("scwin").setReturnValue("text : " + text);          
}




scwin.getTabCount = function () {
    let rtn = target1.getTabCount();

    wf_body_bottom.getObj("scwin").setReturnValue("getTabCount : " + rtn);
}



scwin.btn_addTab_onclick = async function (e) {
    let id = "tabs1";

    let rowJSON = {};  

    await target1.addTab(id,  
        {   
            "label": "newTabs", 
            "title": "dataObject",                        
        }, 
        {   
            "src": "/sample/common_link/tabControl_link_2.xml",
            "frameMode" : "wframePreload",
            "scope" : true, 
            "alwaysDraw": true,
            "dataObject":{
                "type" : "json",
                "name" : "tabParam",
                "data" : rowJSON
            }
        }
    );

    scwin.getTabCount();
    scwin.getAfterAction();
};
